Sure, I'd be happy to help you create a simple task manager program. Here's a Python solution using a list to store tasks and the `input()` function to get user input. This program supports adding, removing, and marking tasks as completed.

```python
tasks = []

def add_task():
    """Add a new task to the list."""
    task_name = input("Enter a task name: ")
    tasks.append({"name": task_name, "completed": False})
    print(f"Task {len(tasks)}: {task_name} (not completed)")

def remove_task():
    """Remove a task from the list."""
    if tasks:
        task_index = int(input("Enter the index of the task to remove: ")) - 1
        if task_index < len(tasks):
            tasks.pop(task_index)
            print(f"Task {task_index + 1} removed.")
        else:
            print("Invalid index. Please try again.")
    else:
        print("No tasks to remove. Please add tasks first.")

def mark_completed():
    """Mark a task as completed."""
    if tasks:
        task_index = int(input("Enter the index of the task to mark as completed: ")) - 1
        if task_index < len(tasks):
            tasks[task_index]["completed"] = True
            print(f"Task {task_index + 1} completed.")
        else:
            print("Invalid index. Please try again.")
    else:
        print("No tasks to mark as completed. Please add tasks first.")

def display_tasks():
    """Display all tasks in the list."""
    if tasks:
        print("Your tasks:")
        for i, task in enumerate(tasks, start=1):
            print(f"{i}. {task['name']} ({'completed' if task['completed'] else 'not completed'})")
    else:
        print("No tasks to display. Please add tasks first.")

# Main loop
while True:
    print("\nAvailable actions:")
    print("1. Add a task")
    print("2. Remove a task")
    print("3. Mark a task as completed")
    print("4. Display tasks")
    print("5. Exit")

    action = input("Enter the number of the action you want to perform: ")

    if action == "1":
        add_task()
    elif action == "2":
        remove_task()
    elif action == "3":
        mark_completed()
    elif action == "4":
        display_tasks()
    elif action == "5":
        print("Exiting the program...")
        break
    else:
        print("Invalid input. Please try again.")
```

This program allows the user to perform various tasks on their tasks list. You can extend it further by adding more features, such as sorting tasks by name or date, or searching for tasks based on their name or completion status.
